  MMR:{fr:["La plaine de Bagan compte plus de 2 000 temples."],en:["The plain of Bagan holds more than 2,000 temples."]},
  MNE:{fr:["Son nom signifie « montagne noire »."],en:["Its name means 'black mountain'."]},
  MNG:{fr:["Le pays le moins densément peuplé du monde.","Beaucoup d'habitants vivent encore sous la yourte."],en:["The least densely populated country on Earth.","Many people still live in round felt tents."]},
  MOZ:{fr:["Son drapeau arbore un fusil AK-47.","Son littoral s'étire sur environ 2 500 km.","L'île de Mozambique a donné son nom au pays."],en:["Its flag features an AK-47 rifle.","Its coastline stretches about 2,500 km.","The Island of Mozambique gave the country its name."]},
  MRT:{fr:["Un de ses trains de minerai est parmi les plus longs du monde.","La structure de Richat, « l'œil de l'Afrique », se voit depuis l'espace.","Le désert couvre environ 90 % du pays."],en:["Home to one of the world's longest trains.","The Richat Structure, the 'Eye of Africa', is visible from space.","Desert covers about 90% of the country."]},
  MUS:{fr:["Le dodo, oiseau disparu, vivait sur cette île.","L'île est née d'éruptions volcaniques.","Un timbre mauricien de 1847 est l'un des plus rares du monde."],en:["The extinct dodo bird lived on this island.","The island was born from volcanic eruptions.","An 1847 Mauritius stamp is one of the rarest in the world."]},
  MWI:{fr:["Le lac Malawi abrite des centaines d’espèces de poissons.","Le lac Malawi couvre environ un quart du pays.","Surnommé « le cœur chaud de l'Afrique »."],en:["Lake Malawi holds hundreds of fish species.","Lake Malawi covers about a quarter of the country.","Nicknamed 'the warm heart of Africa'."]},
  MYS:{fr:["Ses forêts comptent parmi les plus anciennes du monde."],en:["Its rainforests are among the oldest on Earth."]},
  NAM:{fr:["Les dunes du Namib comptent parmi les plus hautes.","Le Namib serait le plus vieux désert du monde.","C'est l'un des pays les moins densément peuplés du monde."],en:["The Namib's dunes are among Earth's tallest.","The Namib may be the world's oldest desert.","One of the least densely populated countries on Earth."]},
  NER:{fr:["Plus des deux tiers du pays sont dans le Sahara.","Le pays doit son nom au fleuve Niger.","L'arbre du Ténéré fut longtemps l'arbre le plus isolé du monde."],en:["More than two-thirds lies in the Sahara.","The country is named after the Niger River.","The Tree of Ténéré was once the loneliest tree on Earth."]},
  NGA:{fr:["Pays le plus peuplé d'Afrique.","Nollywood, son industrie du cinéma, tourne des centaines de films par an.","Plus de 500 langues y sont parlées."],en:["The most populous country in Africa.","Its film industry, Nollywood, shoots hundreds of movies a year.","More than 500 languages are spoken here."]},
  NIC:{fr:["Le lac Nicaragua abrite des requins d'eau douce."],en:["Lake Nicaragua is home to freshwater sharks."]},
  NLD:{fr:["Un quart du pays se trouve sous le niveau de la mer.","Il y a plus de vélos que d'habitants."],en:["A quarter of the country lies below sea level.","There are more bicycles than people."]},
  NOR:{fr:["Ses fjords ont été creusés par les glaciers.","Au nord, le soleil ne se couche pas de l'été."],en:["Its fjords were carved out by glaciers.","In the north the sun does not set all summer."]},
  NPL:{fr:["L'Everest, toit du monde, se dresse à sa frontière.","Son drapeau est le seul au monde qui ne soit pas rectangulaire."],en:["Everest, the roof of the world, stands on its border.","Its flag is the only non-rectangular national flag."]},
  NRU:{fr:["Le plus petit pays insulaire du monde : on en fait le tour en vingt minutes."],en:["The world's smallest island country: you can drive around it in twenty minutes."]},
  NZL:{fr:["Le pays compte environ cinq moutons pour un habitant.","Le kiwi, oiseau qui ne vole pas, n'existe qu'ici."],en:["There are roughly five sheep for every person.","The kiwi, a bird that cannot fly, lives only here."]},
  OMN:{fr:["L'encens du pays s'exportait déjà dans l'Antiquité."],en:["Its frankincense was already being exported in ancient times."]},
  PAK:{fr:["Le K2, deuxième sommet du monde, se dresse à sa frontière.","La vallée de l'Indus abritait une civilisation il y a 4 500 ans."],en:["K2, the world's second-highest peak, rises on its border.","The Indus valley held a civilisation 4,500 years ago."]},
  PAN:{fr:["Son canal relie deux océans en une journée de navigation."],en:["Its canal links two oceans in a single day's sailing."]},
  PER:{fr:["Le Machu Picchu est resté caché dans la montagne pendant des siècles.","La pomme de terre vient des Andes péruviennes."],en:["Machu Picchu stayed hidden in the mountains for centuries.","The potato comes from the Peruvian Andes."]},
  PHL:{fr:["L'archipel compte plus de 7 000 îles."],en:["The archipelago counts more than 7,000 islands."]},
  PLW:{fr:["On y nage au milieu de méduses qui ne piquent pas."],en:["You can swim among jellyfish that do not sting."]},
  PNG:{fr:["On y parle plus de 800 langues, plus que dans tout autre pays."],en:["More than 800 languages are spoken here, more than anywhere else."]},
  POL:{fr:["Marie Curie, deux fois prix Nobel, était polonaise.","La forêt de Białowieża abrite les derniers bisons d'Europe."],en:["Marie Curie, twice a Nobel laureate, was Polish.","Białowieża Forest shelters Europe's last wild bison."]},
  PRK:{fr:["Le pays le plus fermé du monde."],en:["The most closed-off country in the world."]},
  PRT:{fr:["Le pays produit la moitié du liège du monde.","Ses frontières sont presque inchangées depuis le XIIIe siècle."],en:["The country produces half the world's cork.","Its borders have barely changed since the 13th century."]},
  PRY:{fr:["Le pays a deux langues officielles, dont le guarani."],en:["The country has two official languages, one of them Guaraní."]},
  PSE:{fr:["Jéricho est considérée comme l'une des plus anciennes villes du monde."],en:["Jericho is considered one of the oldest cities in the world."]},
